    async fetch_S3_file(value) {
      try {
        const response = await fetch(value);
        if (!response.ok) {
          throw new Error(`Failed to fetch the file: ${response.statusText} (Status Code: ${response.status})`);
        }
        if (!response.headers.get("Content-Type").includes("application/json")) {
          throw new Error("The file is not in JSON format");
        }
        const responseData = await response.text();
        try {
          return JSON.parse(responseData);
        } catch (jsonError) {
          throw new Error("Error parsing JSON response: " + jsonError.message);
        }
      } catch (error) {
        console.error("Error fetching file:", error);
